OPJ_BOOL write_sot_marker(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 p_total_data_size, OPJ_UINT32 *p_data_written, const opj_stream_private_t *p_stream, opj_event_mgr_t *p_manager) {
    if (!p_j2k || !p_data || !p_data_written) {
        return OPJ_FALSE;
    }

    /* SOT marker code is 0xFF91 */
    if (*p_data_written + 2 > p_total_data_size) {
        return OPJ_FALSE;
    }

    p_data[(*p_data_written)++] = 0xFF;
    p_data[(*p_data_written)++] = 0x91;

    return OPJ_TRUE;
}

OPJ_BOOL write_sot_marker(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 p_total_data_size, OPJ_UINT32 *p_data_written, const opj_stream_private_t *p_stream, opj_event_mgr_t *p_manager) {
    OPJ_UNUSED(p_stream);

    if (!p_j2k || !p_data || !p_data_written) {
        return OPJ_FALSE;
    }

    if (p_total_data_size < 14) {
        return OPJ_FALSE;
    }

    p_data[0] = 0xFF;
    p_data[1] = 0x90; /* SOT marker */

    /* Length (4 bytes): 12 (excluding the first 2 bytes) */
    p_data[2] = (OPJ_BYTE)(12 >> 24);
    p_data[3] = (OPJ_BYTE)(12 >> 16);
    p_data[4] = (OPJ_BYTE)(12 >> 8);
    p_data[5] = (OPJ_BYTE)(12);

    /* Tile index (2 bytes), default 0 */
    p_data[6] = 0x00;
    p_data[7] = 0x00;

    /* Tile part index (1 byte), default 0 */
    p_data[8] = 0x00;

    /* Number of tile parts (3 bytes), default 1 */
    p_data[9] = 0x00;
    p_data[10] = 0x00;
    p_data[11] = 0x01;

    /* Data offset (4 bytes), default 16 */
    p_data[12] = 0x00;
    p_data[13] = 0x00;
    p_data[14] = 0x00;
    p_data[15] = 0x10;

    *p_data_written = 16;

    return OPJ_TRUE;
}

OPJ_BOOL write_sot_marker(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 p_total_data_size, OPJ_UINT32 *p_data_written, const opj_stream_private_t *p_stream, opj_event_mgr_t *p_manager) {
    OPJ_UNUSED(p_stream);

    if (!p_j2k || !p_data || !p_data_written) {
        return OPJ_FALSE;
    }

    if (p_total_data_size < 12) {
        return OPJ_FALSE;
    }

    /* Write SOT marker (0xFF91) */
    p_data[0] = 0xFF;
    p_data[1] = 0x91;

    /* Length of the SOT segment (excluding the first two bytes) is 10 bytes */
    p_data[2] = 0x00;
    p_data[3] = 0x0A;

    /* Identifier (Id) of the tile part */
    p_data[4] = 0x00;
    p_data[5] = 0x00;

    /* Index of the progression */
    p_data[6] = 0x00;

    /* Number of layers */
    p_data[7] = 0x00;

    /* Number of components */
    p_data[8] = 0x00;

    /* Index of the tile */
    p_data[9] = 0x00;
    p_data[10] = 0x00;

    *p_data_written = 12;

    return OPJ_TRUE;
}

OPJ_BOOL write_sot_marker(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 p_total_data_size,
                          OPJ_UINT32 *p_data_written, const opj_stream_private_t *p_stream,
                          opj_event_mgr_t *p_manager) {
    OPJ_UINT32 bytes_written = 0;
    OPJ_UINT32 sot_length;

    if (!p_j2k || !p_data || !p_data_written) {
        return OPJ_FALSE;
    }

    /* SOT marker (2 bytes) */
    if (bytes_written + 2 > p_total_data_size) {
        return OPJ_FALSE;
    }
    p_data[bytes_written++] = 0xFF;
    p_data[bytes_written++] = 0x90;

    /* Length of SOT marker (2 bytes) - 4 bytes for header, 18 bytes for data */
    sot_length = 20;
    if (bytes_written + 2 > p_total_data_size) {
        return OPJ_FALSE;
    }
    p_data[bytes_written++] = (OPJ_BYTE)(sot_length >> 8);
    p_data[bytes_written++] = (OPJ_BYTE)(sot_length & 0xFF);

    /* POC (Position of the progression start) - 2 bytes */
    if (bytes_written + 2 > p_total_data_size) {
        return OPJ_FALSE;
    }
    p_data[bytes_written++] = 0x00;
    p_data[bytes_written++] = 0x00;

    /* Tile index - 2 bytes */
    if (bytes_written + 2 > p_total_data_size) {
        return OPJ_FALSE;
    }
    p_data[bytes_written++] = (OPJ_BYTE)(p_j2k->current_tile_number >> 8);
    p_data[bytes_written++] = (OPJ_BYTE)(p_j2k->current_tile_number & 0xFF);

    /* Number of components - 2 bytes */
    if (bytes_written + 2 > p_total_data_size) {
        return OPJ_FALSE;
    }
    p_data[bytes_written++] = (OPJ_BYTE)(p_j2k->numcomps >> 8);
    p_data[bytes_written++] = (OPJ_BYTE)(p_j2k->numcomps & 0xFF);

    /* Data length - 4 bytes */
    if (bytes_written + 4 > p_total_data_size) {
        return OPJ_FALSE;
    }
    p_data[bytes_written++] = 0x00;
    p_data[bytes_written++] = 0x00;
    p_data[bytes_written++] = 0x00;
    p_data[bytes_written++] = 0x00;

    *p_data_written = bytes_written;
    return OPJ_TRUE;
}

OPJ_BOOL write_SOT_marker(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 p_total_data_size, OPJ_UINT32 *p_data_written, const opj_stream_private_t *p_stream, opj_event_mgr_t *p_manager) {
    if (!p_j2k || !p_data || !p_data_written || !p_manager) {
        return OPJ_FALSE;
    }

    if (*p_data_written + 12 > p_total_data_size) {
        return OPJ_FALSE;
    }

    OPJ_UINT32 index = *p_data_written;

    /* Write SOT marker (0xFF91) */
    p_data[index] = 0xFF;
    p_data[index + 1] = 0x91;
    index += 2;

    /* Write Length: 16 bytes (0x0010) */
    p_data[index] = 0x00;
    p_data[index + 1] = 0x10;
    index += 2;

    /* Write Tile index (0x0000) */
    p_data[index] = 0x00;
    p_data[index + 1] = 0x00;
    index += 2;

    /* Write Tile Part index (0x0000) */
    p_data[index] = 0x00;
    p_data[index + 1] = 0x00;
    index += 2;

    /* Write Number of Resolution Levels (1) */
    p_data[index] = 0x01;
    index += 1;

    /* Write Number of Components (1) */
    p_data[index] = 0x01;
    index += 1;

    /* Write X Reference Grid Coordinate of Top-Left (0x0000) */
    p_data[index] = 0x00;
    p_data[index + 1] = 0x00;
    index += 2;

    /* Write Y Reference Grid Coordinate of Top-Left (0x0000) */
    p_data[index] = 0x00;
    p_data[index + 1] = 0x00;
    index += 2;

    *p_data_written = index;

    return OPJ_TRUE;
}
